package com.chatgptcourses.operations.service;

import static com.chatgptcourses.account.service.AccountOperations.*;
import static com.chatgptcourses.operations.service.OperationsTypes.*;
import com.chatgptcourses.commerce.service.OrderService;
import com.chatgptcourses.notifications.NotificationOperations;
import com.chatgptcourses.payments.inbox.PaymentInboxOperations;
import com.chatgptcourses.payments.refunds.RefundService;
import com.chatgptcourses.shared.http.ApiError;
import com.chatgptcourses.shared.http.EntityTags;
import com.chatgptcourses.shared.money.Money;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OperationsService {
    private final OperationsStore db;private final OrderService orders;private final PaymentInboxOperations payments;private final NotificationOperations notifications;private final RefundService refunds;
    public OperationsService(OperationsStore db,OrderService orders,PaymentInboxOperations payments,NotificationOperations notifications,RefundService refunds){this.db=db;this.orders=orders;this.payments=payments;this.notifications=notifications;this.refunds=refunds;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public OperationsDashboard dashboard(UUID actor,Instant from,Instant to){db.auth.require(actor,"operations.read");OperationsStore.period(from,to);var counters=new ArrayList<DashboardCounter>();counter(counters,actor,"ORDERS_CREATED","commerce.orders.admin.read","SELECT count(*)::text FROM orders WHERE created_at>=? AND created_at<?",from,to);counter(counters,actor,"PAYMENTS_CONFIRMED","commerce.orders.admin.read","SELECT count(*)::text FROM orders WHERE payment_status='PAID' AND paid_at>=? AND paid_at<?",from,to);counter(counters,actor,"ACTIVATIONS_READY","commerce.orders.admin.read","SELECT count(*)::text FROM orders WHERE fulfillment_status='READY' AND paid_at>=? AND paid_at<?",from,to);counter(counters,actor,"REFUND_REQUESTS_OPEN","refunds.admin.read","SELECT count(*)::text FROM refund_requests WHERE state='REQUESTED' AND created_at>=? AND created_at<?",from,to);counter(counters,actor,"SUPPORT_OPEN","support.admin.read","SELECT count(*)::text FROM support_tickets WHERE state NOT IN('RESOLVED','CLOSED') AND created_at>=? AND created_at<?",from,to);counter(counters,actor,"CONTENT_CASES_OPEN","content.cases.read","SELECT count(*)::text FROM editorial_cases WHERE state IN('OPEN','IN_PROGRESS') AND created_at>=? AND created_at<?",from,to);if(db.permitted(actor,"operations.incidents.read")&&!allowedKinds(actor).isEmpty())counters.add(new DashboardCounter("INCIDENTS_OPEN",Long.toString(incidents(actor,from,to,null,null,0,1).total()),"AVAILABLE",null));else counters.add(new DashboardCounter("INCIDENTS_OPEN",null,"FORBIDDEN","SOURCE_PERMISSION_REQUIRED"));return new OperationsDashboard(new OperationsPeriod(from,to),db.now().toInstant(),counters);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public AdminOrderPage orders(UUID actor,AdminOrderQuery q){db.auth.require(actor,"commerce.orders.admin.read");check(q!=null);OperationsStore.period(q.from(),q.to());OperationsStore.currency(q.currency());page(q.page(),q.pageSize());if(q.paymentStatus()!=null)check(PAYMENT_STATES.contains(q.paymentStatus()));if(q.fulfillmentStatus()!=null)check(FULFILLMENT_STATES.contains(q.fulfillmentStatus()));String where=" WHERE created_at>=? AND created_at<?";var args=new ArrayList<Object>(List.of(Timestamp.from(q.from()),Timestamp.from(q.to())));if(q.paymentStatus()!=null){where+=" AND payment_status=?";args.add(q.paymentStatus());}if(q.fulfillmentStatus()!=null){where+=" AND fulfillment_status=?";args.add(q.fulfillmentStatus());}if(q.offerId()!=null){where+=" AND offer_id=?";args.add(q.offerId());}if(q.currency()!=null){where+=" AND currency=?";args.add(q.currency());}long total=db.jdbc.queryForObject("SELECT count(*) FROM orders"+where,Long.class,args.toArray());args.add(q.pageSize());args.add((long)q.page()*q.pageSize());var items=db.jdbc.query("SELECT * FROM orders"+where+" ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(r,n)->new AdminOrderSummary(r.getObject("id",UUID.class),r.getObject("owner_id",UUID.class),r.getLong("revision"),r.getObject("offer_id",UUID.class),db.mapper.readTree(r.getString("snapshot_json")).path("title").asText(),new Money(r.getLong("total_amount"),r.getString("currency")),r.getString("order_status"),r.getString("payment_status"),r.getString("fulfillment_status"),instant(r,"created_at"),instant(r,"paid_at")),args.toArray());return new AdminOrderPage(items,q.page(),q.pageSize(),total);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public AdminOrderDetail order(UUID actor,UUID id){var value=orders.adminGet(actor,id);UUID owner=owner(id);var payment=db.jdbc.query("SELECT p.id,p.state,p.session_id,p.payment_intent_id,p.last_error_code FROM checkout_operations p WHERE p.order_id=?",(r,n)->new PaymentReference(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getString(5)),id);var origins=db.jdbc.query("SELECT g.*,v.version_number FROM access_grants g JOIN order_resources r ON r.id=g.order_resource_id JOIN pedagogical_versions v ON v.id=g.version_id WHERE r.order_id=? ORDER BY g.id",(r,n)->new OrderOrigin(r.getObject("id",UUID.class),r.getObject("order_resource_id",UUID.class),r.getObject("resource_id",UUID.class),r.getObject("version_id",UUID.class),r.getInt("version_number"),List.copyOf(Arrays.asList(db.mapper.readValue(r.getString("locales"),String[].class))),instant(r,"revoked_at")!=null?"REVOKED":r.getTimestamp("starts_at").toInstant().isAfter(db.now().toInstant())?"NOT_STARTED":instant(r,"expires_at")!=null&&!r.getTimestamp("expires_at").toInstant().isAfter(db.now().toInstant())?"EXPIRED":"ACTIVE",instant(r,"starts_at"),instant(r,"expires_at"),instant(r,"revoked_at")),id);long confirmed=db.jdbc.queryForObject("SELECT coalesce(sum(amount_minor),0) FROM refund_operations WHERE order_id=? AND confirmed_at IS NOT NULL",Long.class,id);long reserved=db.jdbc.queryForObject("SELECT coalesce(sum(amount_minor),0) FROM refund_reservations WHERE order_id=? AND released_at IS NULL",Long.class,id);boolean review=db.jdbc.queryForObject("SELECT refund_review_required FROM orders WHERE id=?",Boolean.class,id);return new AdminOrderDetail(owner,value,EntityTags.forRevision("order",id,value.revision()),payment.isEmpty()?null:payment.getFirst(),origins,confirmed,reserved,review,!payment.isEmpty()&&db.permitted(actor,"payments.events.retry"));}
    @Transactional
    public OperationReceipt reconcileOrder(UUID actor,UUID context,UUID id,String idem,RequestOrderReconciliation command){db.auth.mutation(actor,context,"payments.events.retry");check(command!=null&&command.expectedOrderRevision()>=0&&Set.of("PROVIDER_RECOVERED","MANUAL_RECONCILIATION").contains(command.reason()));UUID key=key(idem);byte[] hash=db.hash(Arrays.asList(id,command));db.lockParticipants(actor,owner(id));db.auth.mutation(actor,context,"payments.events.retry");var replay=db.replay(actor,"ORDER_RECONCILE",key,hash);if(replay!=null)return receipt(replay.id(),true);UUID job=payments.reconcileOrder(actor,context,id,command.expectedOrderRevision());String state=state("PAYMENT_RECONCILIATION",job);UUID action=db.audit(actor,"ORDER_RECONCILE","ORDER",id,"ORDER_RECONCILIATION",state);db.remember(actor,"ORDER_RECONCILE",key,hash,"RECEIPT",action);return receipt(action,false);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public IncidentPage incidents(UUID actor,Instant from,Instant to,String kind,String state,int page,int size){db.auth.require(actor,"operations.incidents.read");OperationsStore.period(from,to);page(page,size);if(kind!=null)check(KINDS.contains(kind));if(state!=null)check(INCIDENT_STATES.contains(state));var allowed=allowedKinds(actor);if(kind!=null){if(!allowed.contains(kind))db.auth.require(actor,readPermission(kind));allowed=List.of(kind);}if(allowed.isEmpty())return new IncidentPage(List.of(),page,size,0);String slots=String.join(",",allowed.stream().map(k->"?").toList());String where=" WHERE kind IN("+slots+") AND created_at>=? AND created_at<?";var args=new ArrayList<Object>(allowed);args.add(Timestamp.from(from));args.add(Timestamp.from(to));if(state!=null){where+=" AND state=?";args.add(state);}long total=db.jdbc.queryForObject("SELECT count(*) FROM("+INCIDENTS+") x"+where,Long.class,args.toArray());args.add(size);args.add((long)page*size);var values=db.jdbc.query("SELECT * FROM("+INCIDENTS+") x"+where+" ORDER BY created_at DESC,id,kind LIMIT ? OFFSET ?",(r,n)->{String k=r.getString("kind");boolean retry=db.permitted(actor,writePermission(k))&&r.getBoolean("retryable");return new IncidentSummary(r.getObject("id",UUID.class),k,r.getString("state"),r.getString("last_error_code"),r.getObject("order_id",UUID.class),r.getObject("operation_id",UUID.class),instant(r,"created_at"),instant(r,"updated_at"),instant(r,"next_attempt_at"),retry,retry?null:"RETRY_UNAVAILABLE");},args.toArray());return new IncidentPage(values,page,size,total);}
    @Transactional
    public OperationReceipt retryIncident(UUID actor,UUID context,String kind,UUID id,String idem,RetryIncident command){
        db.auth.mutation(actor,context,"operations.incidents.read");
        check(kind!=null&&KINDS.contains(kind)&&command!=null&&command.reason()!=null&&RETRY_REASONS.contains(command.reason()));
        db.auth.require(actor,writePermission(kind));
        UUID key=key(idem);byte[] hash=db.hash(Arrays.asList(kind,id,command));
        // An accepted retry remains replayable after the worker resolves its incident.
        var replay=db.replay(actor,"INCIDENT_RETRY",key,hash);
        if(replay!=null)return receipt(replay.id(),true);
        var original=db.jdbc.query("SELECT owner_id,order_id FROM("+INCIDENTS+") x WHERE id=? AND kind=?",(r,n)->new UUID[]{r.getObject(1,UUID.class),r.getObject(2,UUID.class)},id,kind);
        if(original.isEmpty()){
            // The prior action and its key may have committed between these reads.
            replay=db.replay(actor,"INCIDENT_RETRY",key,hash);
            if(replay!=null){db.auth.mutation(actor,context,"operations.incidents.read");db.auth.require(actor,writePermission(kind));return receipt(replay.id(),true);}
            throw error(ApiError.RESOURCE_NOT_FOUND);
        }
        db.lockParticipants(actor,original.getFirst()[0]);
        db.auth.mutation(actor,context,"operations.incidents.read");db.auth.require(actor,writePermission(kind));
        replay=db.replay(actor,"INCIDENT_RETRY",key,hash);if(replay!=null)return receipt(replay.id(),true);
        String result;
        switch(kind){case "NOTIFICATION"->{String reason=Set.of("SMTP_RECOVERED","PROVIDER_RECOVERED").contains(command.reason())?"CONFIGURATION_FIXED":"MANUAL_RECONCILIATION";result=notifications.retry(actor,context,id,reason,command.ackDuplicate()).status();}
        case "PAYMENT_EVENT","PAYMENT_RECONCILIATION"->{String reason="PROVIDER_RECOVERED".equals(command.reason())?"PROVIDER_RECOVERED":"MANUAL_RECONCILIATION";result=payments.retry(actor,context,id,reason).state();}
        case "CHECKOUT_OPERATION"->{UUID job=payments.reconcileOrder(actor,context,original.getFirst()[1],null);result=state("PAYMENT_RECONCILIATION",job);}
        default->{UUID job=refunds.requestOrderReconciliation(actor,context,original.getFirst()[1]);result=state("REFUND_RECONCILIATION",job);}}
        UUID action=db.audit(actor,"INCIDENT_RETRY",kind,id,"INCIDENT_RETRY",result);db.remember(actor,"INCIDENT_RETRY",key,hash,"RECEIPT",action);return receipt(action,false);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public AuditPage audit(UUID actor,Instant from,Instant to,String source,String action,UUID author,UUID object,int page,int size){db.auth.require(actor,"operations.audit.read");OperationsStore.period(from,to);page(page,size);if(source!=null)check(AUDIT_SOURCES.contains(source));if(action!=null)check(action.matches("[A-Z][A-Z0-9_]{0,63}"));String where=" WHERE occurred_at>=? AND occurred_at<?";var args=new ArrayList<Object>(List.of(Timestamp.from(from),Timestamp.from(to)));if(source!=null){where+=" AND source=?";args.add(source);}if(action!=null){where+=" AND action=?";args.add(action);}if(author!=null){where+=" AND actor_id=?";args.add(author);}if(object!=null){where+=" AND object_id=?";args.add(object);}long total=db.jdbc.queryForObject("SELECT count(*) FROM("+AUDIT+") a"+where,Long.class,args.toArray());args.add(size);args.add((long)page*size);var rows=db.jdbc.query("SELECT * FROM("+AUDIT+") a"+where+" ORDER BY occurred_at DESC,id,source LIMIT ? OFFSET ?",(r,n)->new AuditEvent(r.getObject("id",UUID.class),r.getString("source"),r.getObject("actor_id",UUID.class),r.getString("action"),r.getString("object_type"),r.getObject("object_id",UUID.class),r.getString("reason_code"),r.getString("result"),instant(r,"occurred_at")),args.toArray());return new AuditPage(rows,page,size,total);}
    private void counter(List<DashboardCounter> target,UUID actor,String code,String permission,String sql,Instant from,Instant to){if(!db.permitted(actor,permission))target.add(new DashboardCounter(code,null,"FORBIDDEN","SOURCE_PERMISSION_REQUIRED"));else target.add(new DashboardCounter(code,db.jdbc.queryForObject(sql,String.class,Timestamp.from(from),Timestamp.from(to)),"AVAILABLE",null));}
    private UUID owner(UUID order){var rows=db.jdbc.query("SELECT owner_id FROM orders WHERE id=?",(r,n)->r.getObject(1,UUID.class),order);if(rows.isEmpty())throw error(ApiError.RESOURCE_NOT_FOUND);return rows.getFirst();}
    private OperationReceipt receipt(UUID action,boolean replayed){return db.jdbc.queryForObject("SELECT object_type,object_id,result,occurred_at FROM operations_audit WHERE id=?",(r,n)->new OperationReceipt(action,r.getString(1),r.getObject(2,UUID.class),r.getString(3),r.getTimestamp(4).toInstant(),replayed),action);}
    private String state(String kind,UUID id){String table="PAYMENT_RECONCILIATION".equals(kind)?"payment_reconciliation_jobs":"refund_reconciliation_jobs";return db.jdbc.queryForObject("SELECT state FROM "+table+" WHERE id=?",String.class,id);}
    private List<String> allowedKinds(UUID actor){return KINDS.stream().filter(k->db.permitted(actor,readPermission(k))).sorted().toList();}
    private static String readPermission(String kind){return switch(kind){case "NOTIFICATION"->"notifications.read";case "REFUND_OPERATION","REFUND_RECONCILIATION"->"refunds.admin.read";default->"payments.events.read";};}
    private static String writePermission(String kind){return switch(kind){case "NOTIFICATION"->"notifications.manage";case "REFUND_OPERATION","REFUND_RECONCILIATION"->"refunds.reconcile";default->"payments.events.retry";};}
    private static final Set<String> KINDS=Set.of("NOTIFICATION","PAYMENT_EVENT","PAYMENT_RECONCILIATION","CHECKOUT_OPERATION","REFUND_OPERATION","REFUND_RECONCILIATION");
    private static final Set<String> RETRY_REASONS=Set.of("PROVIDER_RECOVERED","MANUAL_RECONCILIATION","SMTP_RECOVERED","MANUAL_RETRY");
    private static final Set<String> INCIDENT_STATES=Set.of("RETRY","DEAD","INDETERMINATE","UNKNOWN","NEEDS_REVIEW","PROCESSING");
    private static final Set<String> PAYMENT_STATES=Set.of("NOT_STARTED","UNKNOWN","PROCESSING","PAID","FAILED","EXPIRED");
    private static final Set<String> FULFILLMENT_STATES=Set.of("NOT_STARTED","PENDING","RETRYING","NEEDS_REVIEW","READY");
    private static final Set<String> AUDIT_SOURCES=Set.of("EDITORIAL","OFFER","PAYMENT","NOTIFICATION","REFUND","SUPPORT","OPERATIONS");
    private static final String INCIDENTS="""
      SELECT n.id,'NOTIFICATION'::text kind,n.status state,n.last_error_code,NULL::uuid order_id,NULL::uuid operation_id,n.created_at,n.updated_at,n.next_attempt_at,n.owner_id,(n.payload_ciphertext IS NOT NULL AND n.expires_at>clock_timestamp()) retryable FROM notification_outbox n WHERE n.status IN('RETRY','DEAD','INDETERMINATE')
      UNION ALL SELECT e.id,'PAYMENT_EVENT',e.state,e.last_error_code,e.order_id,e.operation_id,e.created_at,e.updated_at,e.next_attempt_at,o.owner_id,true FROM stripe_event_inbox e LEFT JOIN orders o ON o.id=e.order_id WHERE e.state IN('RETRY','DEAD') OR(e.state='PROCESSING' AND e.lease_until<=clock_timestamp())
      UNION ALL SELECT j.id,'PAYMENT_RECONCILIATION',j.state,j.last_error_code,j.order_id,j.operation_id,j.created_at,j.updated_at,j.next_attempt_at,o.owner_id,true FROM payment_reconciliation_jobs j JOIN orders o ON o.id=j.order_id WHERE j.state IN('RETRY','DEAD') OR(j.state='PROCESSING' AND j.lease_until<=clock_timestamp())
      UNION ALL SELECT p.id,'CHECKOUT_OPERATION',p.state,p.last_error_code,p.order_id,p.id,p.created_at,p.updated_at,NULL::timestamptz,p.owner_id,true FROM checkout_operations p WHERE p.state IN('UNKNOWN','NEEDS_REVIEW')
      UNION ALL SELECT p.id,'REFUND_OPERATION',p.state,p.last_error_code,p.order_id,o.payment_operation_id,p.created_at,p.updated_at,NULL::timestamptz,p.owner_id,true FROM refund_operations p JOIN orders o ON o.id=p.order_id WHERE p.state IN('UNKNOWN','NEEDS_REVIEW')
      UNION ALL SELECT j.id,'REFUND_RECONCILIATION',j.state,j.last_error_code,j.order_id,o.payment_operation_id,j.created_at,j.updated_at,j.next_attempt_at,o.owner_id,true FROM refund_reconciliation_jobs j JOIN orders o ON o.id=j.order_id WHERE j.state IN('RETRY','DEAD') OR(j.state='PROCESSING' AND j.lease_until<=clock_timestamp())
      """;
    private static final String AUDIT="""
      SELECT id,'OPERATIONS'::text source,actor_id,action,object_type,object_id,reason_code,result,occurred_at FROM operations_audit
      UNION ALL SELECT id,'EDITORIAL',actor_id,event_type,'CONTENT_TRANSLATION',translation_id,'EDITORIAL_CHANGE','RECORDED',created_at FROM editorial_events
      UNION ALL SELECT id,'OFFER',actor_id,event_type,'OFFER',offer_id,'OFFER_CHANGE','RECORDED',created_at FROM offer_events
      UNION ALL SELECT id,'PAYMENT',actor_id,'RETRY','PAYMENT_WORK',coalesce(inbox_id,reconciliation_id),'PAYMENT_RETRY','QUEUED',created_at FROM payment_work_retries
      UNION ALL SELECT id,'NOTIFICATION',actor_id,'RETRY','NOTIFICATION',notification_id,'EMAIL_RETRY','QUEUED',created_at FROM notification_outbox_requeues
      UNION ALL SELECT id,'REFUND',actor_id,action,'REFUND',coalesce(operation_id,request_id,order_id),'REFUND_ACTION',result,created_at FROM refund_audit
      UNION ALL SELECT id,'SUPPORT',actor_id,event_type,'SUPPORT_TICKET',ticket_id,'SUPPORT_WORK','RECORDED',created_at FROM support_ticket_events WHERE author_kind='SUPPORT'
      """;
}
